import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M13.287 3.958a1 1 0 0 0-.575-1.916l-10 3c-.95.285-.95 1.63 0 1.916l10 3a1 1 0 0 0 .575-1.916L6.48 6zM13 12H3a1 1 0 0 0 0 2h10a1 1 0 0 0 0-2"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M16.316 11.051 7.162 8l9.154-3.051a1 1 0 1 0-.632-1.898l-12 4c-.912.304-.912 1.594 0 1.898l12 4a1 1 0 1 0 .632-1.898M16 15H4a1 1 0 1 0 0 2h12a1 1 0 1 0 0-2"] as readonly string[];

export const LessThanOrEqualToIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="less-than-or-equal-to" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
LessThanOrEqualToIcon.displayName = `Blueprint6.Icon.LessThanOrEqualToIcon`;

/**
 * @deprecated Use {@link LessThanOrEqualToIcon} instead.
 */
export const LessThanOrEqualTo: typeof LessThanOrEqualToIcon = LessThanOrEqualToIcon;

export default LessThanOrEqualToIcon;
